  if (rhs.ai_ot_apis_enabled < lhs.ai_ot_apis_enabled)
    return false;
  if (lhs.is_indigo_onboarding < rhs.is_indigo_onboarding)
    return true;
  if (rhs.is_indigo_onboarding < lhs.is_indigo_onboarding)
    return false;
